/**
 * bundleArtifactIntel.js — Client-bundle artifact & framework intelligence engine.
 *
 * During a hunt on an authorized target, the agent downloads the target's own
 * publicly served HTML/JS/CSS and mines build artifacts left behind by the
 * toolchain: SWC/Babel transpile helpers, polyfill-service scripts, framework
 * runtimes (Zone.js, RxJS, NgRx, Vuex, Pinia). Each artifact reveals two
 * things the agent needs: (1) the exact build toolchain and versions, which
 * narrows the attack-surface model, and (2) data-flow / endpoint hints — API
 * calls, store actions, and effects embedded in the bundle.
 *
 * All functions are pure and deterministic: they operate only on the asset
 * text handed to them. No network calls, no side effects. Defensive/product
 * framing only — client-asset surface mapping of an authorized target's own
 * publicly served files. No exploit payloads, no weaponized code.
 */

const EP_REGEX =
  /fetch\s*\(\s*['"`]([^'"`]+)['"`]|[a-zA-Z_$][\w$]*\.(get|post|put|patch|delete|request)\s*\(\s*['"`]([^'"`]+)['"`]|\$http\.(get|post|put|patch|delete)\s*\(\s*['"`]([^'"`]+)['"`]|url\s*:\s*['"`]([^'"`]+)['"`]/gi;

/**
 * Extract endpoint-ish string literals that look like data-flow targets from a
 * block of source text. Returns a de-duplicated array of URL/path strings.
 *
 * @param {string} src - JavaScript source to scan.
 * @returns {string[]} Candidate endpoint strings.
 */
function extractEndpoints(src) {
  const found = new Set();
  let m;
  const re = new RegExp(EP_REGEX.source, 'gi');
  while ((m = re.exec(src)) !== null) {
    const candidate = m[1] || m[3] || m[5] || m[6];
    if (candidate && /[/:]/.test(candidate)) found.add(candidate);
  }
  return [...found];
}

const SWC_BANNERS = [
  /Generated by SWC/i,
  /@swc\//i,
  /swcHelpers/i,
  /_swc\w*helper/i,
  /\* Generated by (swc|Speedy Web Compiler)/i,
  /swcHelpers\.\w+/,
];

const SWC_VERSION_COMMENTS = [
  /(?:\*|!|\/\/)?\s*swc\s+v?(\d+\.\d+\.\d+(?:-[\w.]+)?)/i,
  /@swc\/core@(\d+\.\d+\.\d+(?:-[\w.]+)?)/,
];

/**
 * Mine SWC transpile artifacts for original-source hints and version data.
 *
 * Looks for SWC banners, swcHelpers usage, and inline version comments that
 * bundled output sometimes retains, plus sourceMappingURL hints when present.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{swcDetected:boolean,version:string|null,helpers:string[],sourceHints:string[],sourceMapUrl:string|null}} SWC intel.
 */
export function mineSwcTransformArtifacts(js = '') {
  const src = String(js || '');
  const swcDetected = SWC_BANNERS.some((r) => r.test(src));
  let version = null;
  for (const r of SWC_VERSION_COMMENTS) {
    const m = src.match(r);
    if (m) {
      version = m[1];
      break;
    }
  }
  const helpers = new Set();
  const helperRe = /(swcHelpers\.|_swc)\w+/g;
  let m;
  while ((m = helperRe.exec(src)) !== null) helpers.add(m[0]);
  const sourceHints = new Set();
  const nameRe = /_swc[A-Z]\w*__\w+/g;
  while ((m = nameRe.exec(src)) !== null) sourceHints.add(m[0]);
  const sm = src.match(/sourceMappingURL=([^\s*'"]+)/);
  return {
    swcDetected,
    version,
    helpers: [...helpers],
    sourceHints: [...sourceHints],
    sourceMapUrl: sm ? sm[1] : null,
  };
}

const BABEL_HELPERS = {
  _asyncToGenerator: ['plugin-transform-async-to-generator', '@babel/plugin-transform-async-generator-functions'],
  _classCallCheck: ['plugin-transform-classes'],
  _createClass: ['plugin-transform-classes'],
  _inherits: ['plugin-transform-classes'],
  _interopRequireDefault: ['plugin-transform-modules-commonjs'],
  _interopRequireWildcard: ['plugin-transform-modules-commonjs'],
  _typeof: ['plugin-transform-typeof-symbol'],
  _regeneratorRuntime: ['plugin-transform-regenerator'],
  _taggedTemplateLiteral: ['plugin-transform-template-literals'],
  _objectSpread: ['plugin-proposal-object-rest-spread', 'plugin-transform-object-rest-spread'],
  _defineProperty: ['plugin-transform-property-mutators'],
  _slicedToArray: ['plugin-transform-destructuring'],
  _toConsumableArray: ['plugin-transform-spread'],
  _possibleConstructorReturn: ['plugin-transform-classes'],
  _getPrototypeOf: ['plugin-transform-classes'],
};

const BABEL_COMMENT_PLUGINS = [
  /@babel\/plugin-[\w-]+/g,
  /babel-plugin-[\w-]+/g,
];

/**
 * Fingerprint Babel plugins from the helper functions and plugin names left
 * in bundled output (helpers are inlined, plugin names often survive in
 * comments or `__helpers` metadata).
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{babelDetected:boolean,helpers:string[],plugins:string[],transformed:boolean}} Babel intel.
 */
export function fingerprintBabelPlugins(js = '') {
  const src = String(js || '');
  const helpers = Object.keys(BABEL_HELPERS).filter((h) =>
    new RegExp(`\\b${h}\\b`).test(src)
  );
  const plugins = new Set();
  helpers.forEach((h) => BABEL_HELPERS[h].forEach((p) => plugins.add(p)));
  for (const re of BABEL_COMMENT_PLUGINS) {
    let m;
    const rr = new RegExp(re.source, 'g');
    while ((m = rr.exec(src)) !== null) plugins.add(m[0]);
  }
  const transformed =
    helpers.length > 0 || plugins.size > 0 || /\b_babelRuntime\b/.test(src);
  return {
    babelDetected: transformed,
    helpers,
    plugins: [...plugins],
    transformed,
  };
}

const POLYFILL_SERVICES = [
  { name: 'polyfill.io', hosts: ['polyfill.io', 'cdn.polyfill.io', 'polyfill-fastly.io'] },
  { name: 'polyfill-service', hosts: ['polyfill-service', 'cdnjs.cloudflare.com'] },
  { name: 'core-js CDN', hosts: ['cdn.jsdelivr.net/npm/core-js', 'unpkg.com/core-js'] },
];

/**
 * Map third-party polyfill.io-style services referenced by the page and the
 * feature sets they request (feature query params reveal which APIs the app
 * expects — and which legacy shims an attacker can count on).
 *
 * @param {string} htmlOrJs - HTML or JS text to scan.
 * @returns {{service:string,host:string,features:string[],url:string}[]} Polyfill references.
 */
export function mapPolyfillServices(htmlOrJs = '') {
  const src = String(htmlOrJs || '');
  const results = [];
  const scriptRe = /<script[^>]+src\s*=\s*["']([^"']+)["'][^>]*>/gi;
  let m;
  while ((m = scriptRe.exec(src)) !== null) {
    const url = m[1];
    const service = POLYFILL_SERVICES.find((s) => s.hosts.some((h) => url.includes(h)));
    if (!service) continue;
    let features = [];
    try {
      const q = url.split('?')[1] || '';
      const params = new URLSearchParams(q);
      const f = params.get('features') || params.get('feature');
      if (f) features = f.split(',').map((s) => s.trim()).filter(Boolean);
    } catch {
      features = [];
    }
    results.push({
      service: service.name,
      host: (() => {
        try {
          return new URL(url, 'https://placeholder.local').host;
        } catch {
          return url;
        }
      })(),
      features,
      url,
    });
  }
  return results;
}

const COREJS_VERSION_PATTERNS = [
  /core-js@(\d+\.\d+\.\d+(?:-[\w.]+)?)/,
  /core-js\s*(?:version\s*)?(\d+\.\d+\.\d+(?:-[\w.]+)?)/i,
  /core-js-pure@(\d+\.\d+\.\d+(?:-[\w.]+)?)/,
  /core_js:\s*(\d+\.\d+\.\d+)/i,
];

const COREJS_MODULE_MARKERS = [
  'es.array.at',
  'es.promise.finally',
  'es.global-this',
  'web.url',
  'esnext.async-iterator',
  'es.symbol.async-dispose',
];

/**
 * Detect core-js versions from polyfill bundle banners and module markers.
 * Version matters: old core-js bundles are known vulnerable dependency
 * versions the agent should flag for the target owner to patch.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{detected:boolean,version:string|null,modules:string[],vulnerable:boolean}} core-js intel.
 */
export function detectCoreJsVersion(js = '') {
  const src = String(js || '');
  let version = null;
  for (const r of COREJS_VERSION_PATTERNS) {
    const m = src.match(r);
    if (m) {
      version = m[1];
      break;
    }
  }
  const modules = COREJS_MODULE_MARKERS.filter((mod) => src.includes(mod));
  const detected = version !== null || modules.length > 0 || /core-js/.test(src);
  let vulnerable = false;
  if (version) {
    const [maj] = version.split('.').map((n) => parseInt(n, 10) || 0);
    vulnerable = maj < 3;
  }
  return { detected, version, modules, vulnerable };
}

const REGENERATOR_MARKERS = [
  /regeneratorRuntime/,
  /regenerator-runtime/,
  /_regeneratorRuntime/,
  /function\s+regeneratorRuntime/,
  /require\(['"]regenerator-runtime['"]\)/,
];

/**
 * Detect the regenerator runtime (transpiled async/await or generators) and
 * pull the async call sites around it as data-flow hints.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{detected:boolean,variant:string|null,asyncContexts:string[]}} Regenerator intel.
 */
export function detectRegeneratorRuntime(js = '') {
  const src = String(js || '');
  const matched = REGENERATOR_MARKERS.find((r) => r.test(src));
  const detected = Boolean(matched);
  let variant = null;
  if (detected) {
    const v = src.match(/regenerator-runtime(?:@|[\/])(\d+\.\d+\.\d+(?:-[\w.]+)?)/);
    variant = v ? `regenerator-runtime@${v[1]}` : 'inline regeneratorRuntime';
  }
  const asyncContexts = new Set();
  const fnRe = /(?:async\s+function|function\*)\s*([A-Za-z_$][\w$]*)/g;
  let m;
  while ((m = fnRe.exec(src)) !== null) asyncContexts.add(m[1]);
  return { detected, variant, asyncContexts: [...asyncContexts] };
}

const ZONEJS_PATCH_MARKERS = [
  'Zone.__load_patch',
  'Zone.current',
  'zone.js/dist',
  'ZoneDelegate',
  'zoneSymbol',
  'onScheduleTask',
  'onInvokeTask',
];

const ZONEJS_KNOWN_PATCHES = [
  'promise',
  'fetch',
  'XMLHttpRequest',
  'EventTarget',
  'setTimeout',
  'geolocation',
  'MutationObserver',
  'Notification',
];

/**
 * Map Zone.js patches in an Angular app's bundle — patched async APIs tell
 * the agent which async channels the app's data flows through.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{detected:boolean,patches:string[],asyncChannels:string[],version:string|null}} Zone.js intel.
 */
export function mapZoneJsPatches(js = '') {
  const src = String(js || '');
  const detected = ZONEJS_PATCH_MARKERS.some((marker) => src.includes(marker));
  const patches = new Set();
  const loadRe = /__load_patch\s*\(\s*['"`]([^'"`]+)['"`]/g;
  let m;
  while ((m = loadRe.exec(src)) !== null) patches.add(m[1]);
  const asyncChannels = ZONEJS_KNOWN_PATCHES.filter((p) =>
    new RegExp(`['"\`]${p}['"\`]`, 'i').test(src) || patches.has(p)
  );
  const vm = src.match(/zone\.js@(\d+\.\d+\.\d+(?:-[\w.]+)?)/i);
  return {
    detected,
    patches: [...patches],
    asyncChannels,
    version: vm ? vm[1] : null,
  };
}

const RXJS_OPERATORS = [
  'switchMap', 'mergeMap', 'concatMap', 'exhaustMap', 'map', 'filter', 'tap',
  'catchError', 'retry', 'debounceTime', 'distinctUntilChanged', 'combineLatest',
  'forkJoin', 'zip', 'scan', 'reduce', 'take', 'takeUntil', 'first', 'shareReplay',
  'flatMap', 'pluck', 'delay', 'timeout', 'withLatestFrom', 'startWith',
];

/**
 * Mine RxJS operators from a bundle and, for each operator chain, capture the
 * surrounding data-flow context (HTTP calls, Subjects) as endpoint hints.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{rxjsDetected:boolean,operators:string[],chains:{operator:string,endpoints:string[]}[],version:string|null}} RxJS intel.
 */
export function mineRxjsOperators(js = '') {
  const src = String(js || '');
  const rxjsDetected =
    /from\s+['"]rxjs['"]|require\(['"]rxjs['"]\)|rxjs\/operators/.test(src) ||
    RXJS_OPERATORS.some((op) => new RegExp(`\\.${op}\\s*\\(`).test(src));
  const operators = RXJS_OPERATORS.filter((op) => new RegExp(`\\b${op}\\s*\\(`).test(src));
  const chains = operators.map((op) => {
    const re = new RegExp(`\\b${op}\\s*\\(([\\s\\S]{0,400})`, 'g');
    const endpoints = new Set();
    let m;
    while ((m = re.exec(src)) !== null) {
      extractEndpoints(m[1]).forEach((e) => endpoints.add(e));
    }
    return { operator: op, endpoints: [...endpoints] };
  });
  const vm = src.match(/rxjs@(\d+\.\d+\.\d+(?:-[\w.]+)?)/i);
  return { rxjsDetected, operators, chains, version: vm ? vm[1] : null };
}

const NGRX_PATTERNS = {
  createReducer: /createReducer\s*\(\s*([A-Za-z_$][\w$]*)\s*,/,
  createFeatureSelector: /createFeatureSelector\s*<[^>]*>\s*\(\s*['"`]([^'"`]+)['"`]/,
  storeModule: /StoreModule\.forRoot\s*\(\s*\{([^}]{0,500})\}/,
  effect: /createEffect\s*\(\s*\(\s*\)\s*=>/,
};

/**
 * Extract NgRx store shapes (reducers, feature selectors, effects) for state
 * and API mapping — actions/effects embed the app's API surface.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{detected:boolean,reducers:string[],featureSelectors:string[],storeModules:string[],effects:number,endpoints:string[]}} NgRx intel.
 */
export function extractNgRxStoreShapes(js = '') {
  const src = String(js || '');
  const reducers = new Set();
  const onRe = /createReducer\s*\(\s*([A-Za-z_$][\w$]*)\s*,/g;
  let m;
  while ((m = onRe.exec(src)) !== null) reducers.add(m[1]);
  const featureSelectors = new Set();
  const fsRe = /createFeatureSelector\s*(?:<[^>]*>)?\s*\(\s*['"`]([^'"`]+)['"`]/g;
  while ((m = fsRe.exec(src)) !== null) featureSelectors.add(m[1]);
  const storeModules = new Set();
  const smRe = /StoreModule\.for(Root|Feature)\s*\(\s*['"`]?([\w$-]*)/g;
  while ((m = smRe.exec(src)) !== null) storeModules.add(m[1] === 'Root' ? 'root' : m[2] || 'feature');
  const fmRe = /StoreModule\.forRoot\s*\(\s*\{([^}]{0,500})\}/;
  const fm = src.match(fmRe);
  if (fm) {
    fm[1].split(',').forEach((pair) => {
      const key = pair.split(':')[0].trim();
      if (/^[A-Za-z_$][\w$]*$/.test(key)) storeModules.add(key);
    });
  }
  const effects = (src.match(/createEffect\s*\(/g) || []).length;
  const detected =
    reducers.size > 0 || effects > 0 || storeModules.size > 0 || /@ngrx\/store/.test(src);
  const endpoints = extractEndpoints(src);
  return {
    detected,
    reducers: [...reducers],
    featureSelectors: [...featureSelectors],
    storeModules: [...storeModules],
    effects,
    endpoints,
  };
}

const VUEX_PATTERNS = {
  newStore: /new\s+Vuex\.Store\s*\(\s*\{([\s\S]{0,1200})\}/,
  defineModule: /(?:modules\s*:\s*\{)([\s\S]{0,1200})/,
};

/**
 * Map Vuex modules to their API actions — actions commit mutations and call
 * the backend, so each action is a candidate API endpoint entry point.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{detected:boolean,modules:string[],actions:{module:string,action:string,endpoints:string[]}[]}} Vuex intel.
 */
export function mapVuexModules(js = '') {
  const src = String(js || '');
  const detected = /Vuex\.Store|vuex/.test(src);
  const modules = new Set();
  const modRe = /modules\s*:\s*\{([\s\S]{0,1500})/;
  const mm = src.match(modRe);
  if (mm) {
    const nameRe = /([A-Za-z_$][\w$]*)\s*:\s*\{/g;
    let m2;
    while ((m2 = nameRe.exec(mm[1])) !== null) {
      if (!['state', 'getters', 'mutations', 'actions', 'namespaced'].includes(m2[1])) {
        modules.add(m2[1]);
      }
    }
  }
  const actions = [];
  const actionBlockRe = /actions\s*:\s*\{([\s\S]{0,2000})\}/g;
  let block;
  while ((block = actionBlockRe.exec(src)) !== null) {
    const body = block[1];
    const endpoints = extractEndpoints(body);
    const keyRe = /([A-Za-z_$][\w$]*)\s*[\(:]/g;
    let k;
    while ((k = keyRe.exec(body)) !== null) {
      const name = k[1];
      if (!['async', 'await', 'return', 'commit', 'dispatch', 'state', 'rootState', 'getters'].includes(name)) {
        actions.push({ module: [...modules][0] || 'unknown', action: name, endpoints });
      }
    }
  }
  return { detected, modules: [...modules], actions };
}

const PINIA_PATTERNS = {
  defineStoreOptions: /defineStore\s*\(\s*['"`]([^'"`]+)['"`]\s*,\s*\{([\s\S]{0,2500})\}/,
  defineStoreSetup: /defineStore\s*\(\s*['"`]([^'"`]+)['"`]\s*,\s*\(\s*\)\s*=>\s*\{([\s\S]{0,2500})\}/,
  defineStoreIdRef: /defineStore\s*\(\s*\(\s*\)\s*=>\s*['"`]([^'"`]+)['"`]/,
};

/**
 * Extract Pinia stores (options and setup styles) with their actions and the
 * endpoints those actions touch.
 *
 * @param {string} js - JavaScript bundle text.
 * @returns {{detected:boolean,stores:{name:string,state:string[],actions:{name:string,endpoints:string[]}[]}[]}} Pinia intel.
 */
export function extractPiniaStores(js = '') {
  const src = String(js || '');
  const detected = /defineStore\s*\(/.test(src) || /pinia/.test(src);
  const stores = [];
  const seen = new Set();
  const scanBody = (name, body) => {
    if (seen.has(name)) return;
    seen.add(name);
    const state = new Set();
    const stateBlock = body.match(/state\s*:\s*\(\s*\)\s*=>\s*\(\s*\{([\s\S]{0,800})/);
    if (stateBlock) {
      const keyRe = /([A-Za-z_$][\w$]*)\s*:/g;
      let k;
      while ((k = keyRe.exec(stateBlock[1])) !== null) state.add(k[1]);
    }
    const actions = [];
    const actionBlock = body.match(/actions\s*:\s*\{([\s\S]{0,2500})\}/);
    if (actionBlock) {
      const ab = actionBlock[1];
      const endpoints = extractEndpoints(ab);
      const fnRe = /(?:async\s+)?([A-Za-z_$][\w$]*)\s*\([^)]*\)\s*\{/g;
      let f;
      while ((f = fnRe.exec(ab)) !== null) {
        if (!['if', 'for', 'while', 'catch', 'switch'].includes(f[1])) {
          actions.push({ name: f[1], endpoints });
        }
      }
    }
    stores.push({ name, state: [...state], actions });
  };
  let m;
  const optRe = new RegExp(PINIA_PATTERNS.defineStoreOptions.source, 'g');
  while ((m = optRe.exec(src)) !== null) scanBody(m[1], m[2]);
  const setupRe = new RegExp(PINIA_PATTERNS.defineStoreSetup.source, 'g');
  while ((m = setupRe.exec(src)) !== null) scanBody(m[1], m[2]);
  return { detected, stores };
}

/**
 * Run every bundle-artifact intelligence extractor over one asset bundle.
 * Convenience entry point for the hunt pipeline.
 *
 * @param {string} jsOrHtml - Bundle text (JS or HTML) from the authorized target.
 * @returns {object} All ten extraction results keyed by idea number.
 */
export function analyzeBundleArtifacts(jsOrHtml = '') {
  return {
    swc: mineSwcTransformArtifacts(jsOrHtml),
    babel: fingerprintBabelPlugins(jsOrHtml),
    polyfillServices: mapPolyfillServices(jsOrHtml),
    coreJs: detectCoreJsVersion(jsOrHtml),
    regenerator: detectRegeneratorRuntime(jsOrHtml),
    zoneJs: mapZoneJsPatches(jsOrHtml),
    rxjs: mineRxjsOperators(jsOrHtml),
    ngrx: extractNgRxStoreShapes(jsOrHtml),
    vuex: mapVuexModules(jsOrHtml),
    pinia: extractPiniaStores(jsOrHtml),
  };
}

export default analyzeBundleArtifacts;
